corrected_code:
app.post('/api/sessions/:sessionId/blacklist', authenticateUser, async (req, res) => {
  const { sessionId } = req.params;

  const sessionData = await redisClient.get(`refresh_session:${sessionId}`);
  if (!sessionData) {
    return res.status(404).json({ error: 'Session not found' });
  }

  const session = JSON.parse(sessionData);
  if (session.userId !== req.user.id) {
    return res.status(403).json({ error: 'Forbidden: you cannot revoke another user session' });
  }

  await redisClient.del(`refresh_session:${sessionId}`);
  res.json({ message: 'Session successfully revoked', sessionId });
});
